import{_ as i,C as a,o as n,c as d,a6 as s,E as t}from"./chunks/framework.CMg4qq8Q.js";const v=JSON.parse('{"title":"CORS","description":"Origin reflection, trusted null origins, insecure protocols, and what the same-origin policy actually protects.","frontmatter":{"title":"CORS","description":"Origin reflection, trusted null origins, insecure protocols, and what the same-origin policy actually protects."},"headers":[],"relativePath":"cors/index.md","filePath":"cors/index.md"}'),c={name:"cors/index.md"};function l(p,e,h,g,u,m){const o=a("LabGroup"),r=a("TopicComplete");return n(),d("div",null,[e[0]||(e[0]=s('<h1 id="cross-origin-resource-sharing-cors-·-the-case-of-the-open-door" tabindex="-1">Cross-Origin Resource Sharing (CORS) · The Case of the Open Door <a class="header-anchor" href="#cross-origin-resource-sharing-cors-·-the-case-of-the-open-door" aria-label="Permalink to &quot;Cross-Origin Resource Sharing (CORS) · The Case of the Open Door&quot;">​</a></h1><p class="wd-section-lede">CORS (Cross-Origin Resource Sharing) is not a vulnerability in itself—it is a controlled door in the browser&#39;s Same-Origin Policy. By default, web browsers strictly forbid scripts on one website from reading private data fetched from another website. CORS allows a server to relax this restriction. The vulnerability arises when a server gives that read permission away to everyone, trusts invalid origins, or echoes back whatever domain happens to ask.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Overly Polite Receptionist.</strong> Imagine a company office where confidential customer files are kept behind a front desk. Company rules state that only badged staff may read the files. A visitor arrives wearing a badge from a rival firm and asks: <em>&quot;May I have copies of your customer records?&quot;</em> Instead of verifying the visitor against an approved contractor list, the polite receptionist simply repeats the guest&#39;s badge name: <em>&quot;Welcome, rival-firm.com! Here is full access to the filing cabinet.&quot;</em></p></div><h2 id="case-file-1-tracing-the-reflected-origin-trap" tabindex="-1">Case File #1: Tracing the Reflected Origin Trap <a class="header-anchor" href="#case-file-1-tracing-the-reflected-origin-trap" aria-label="Permalink to &quot;Case File #1: Tracing the Reflected Origin Trap&quot;">​</a></h2><p>Let&#39;s follow what happens when an attacker tries to read your account details using a cross-origin script.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You are logged into your shopping account on <code>store.example</code>. In another tab, you browse a totally unrelated entertainment blog on <code>evil.example</code>. The blog looks normal and no alerts appear.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>JavaScript running on <code>evil.example</code> issues a cross-origin <code>fetch()</code> request to <code>https://store.example/accountDetails</code>. The browser adds an <code>Origin: https://evil.example</code> header. The store&#39;s backend blindly copies that origin into its response headers:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Server CORS Configuration</span><span><span class="wd-code-input">Gold</span> = Reflected Origin Header</span></div><span class="wd-code-dev">HTTP/1.1 200 OK</span><br><span class="wd-code-dev">Access-Control-Allow-Origin: </span><span class="wd-code-input">https://evil.example</span><br><span class="wd-code-dev">Access-Control-Allow-Credentials: true</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The browser inspects the response headers. Because the server explicitly granted permission to <code>evil.example</code> and allowed credentials (<code>Access-Control-Allow-Credentials: true</code>), the browser releases the response body to the attacker&#39;s script—exposing the victim&#39;s email, private address, and API keys!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers configure strict server-side allow-lists containing only explicitly trusted domain names. If the request&#39;s <code>Origin</code> header does not match the allow-list, the server does not send the <code>Access-Control-Allow-Origin</code> header, keeping the data safely protected by the Same-Origin Policy.</p></div></div><h3 id="visual-comparison-intended-api-sharing-vs-universal-origin-reflection" tabindex="-1">Visual Comparison: Intended API Sharing vs. Universal Origin Reflection <a class="header-anchor" href="#visual-comparison-intended-api-sharing-vs-universal-origin-reflection" aria-label="Permalink to &quot;Visual Comparison: Intended API Sharing vs. Universal Origin Reflection&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer wanted their frontend mobile site or trusted partner domain to read API data seamlessly without getting blocked by browser cross-origin security rules.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>By echoing whatever <code>Origin</code> header arrived in the request, the server inadvertently allowed every malicious site on the internet to read authenticated, confidential responses.</p></div></div><hr><h2 id="the-cross-origin-request-lifecycle" tabindex="-1">The Cross-Origin Request Lifecycle <a class="header-anchor" href="#the-cross-origin-request-lifecycle" aria-label="Permalink to &quot;The Cross-Origin Request Lifecycle&quot;">​</a></h2><p>How the browser handles a cross-origin request depends on whether it is classified as a <strong>simple request</strong> or requires a <strong>preflight check</strong>:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Script Issues Fetch</strong> External page initiates cross-origin request with <code>credentials: &#39;include&#39;</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. Browser Stamped Origin</strong> Browser automatically adds authentic <code>Origin: https://evil.example</code> header. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>3. Preflight OPTIONS (if complex)</strong> Checks allowed methods, headers, and credentials before sending real request. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>4. Server Response Headers</strong> Server answers with <code>ACAO</code> and <code>ACAC</code> access directives. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Browser Enforcement</strong> Browser permits script to read response body or blocks access. </div></div><details class="details custom-block"><summary>🔬 Under the Hood: Why Credentials Change the Rules</summary><ul><li><strong>Wildcard Origins:</strong> A server can send <code>Access-Control-Allow-Origin: *</code> for public data. However, the browser <strong>strictly rejects</strong> the wildcard if <code>Access-Control-Allow-Credentials: true</code> is set.</li><li><strong>Credentialed Requests:</strong> To read authenticated responses (which include cookies or HTTP authentication), the server must return an explicit, concrete origin in <code>Access-Control-Allow-Origin</code>.</li><li><strong>Cache Poisoning Prevention:</strong> If a server dynamically reflects the origin, it must include the <code>Vary: Origin</code> header. Otherwise, a shared caching proxy might store a response authorized for an attacker and serve it to legitimate users!</li></ul></details><hr><h2 id="origin-reflection-the-universal-pass" tabindex="-1">Origin Reflection: The Universal Pass <a class="header-anchor" href="#origin-reflection-the-universal-pass" aria-label="Permalink to &quot;Origin Reflection: The Universal Pass&quot;">​</a></h2><p>The most common CORS vulnerability occurs when developers want to support multiple internal subdomains, and solve it by simply copying the incoming <code>Origin</code> header directly into <code>Access-Control-Allow-Origin</code>.</p><p>An attacker&#39;s page on any domain can send a credentialed request, receive full read authorization from the browser, and exfiltrate the victim&#39;s sensitive data.</p>',17)),t(o,{ids:"cors-lab-basic-origin-reflection-attack"}),e[1]||(e[1]=s('<hr><h2 id="the-trusted-null-origin-trap" tabindex="-1">The Trusted <code>null</code> Origin Trap <a class="header-anchor" href="#the-trusted-null-origin-trap" aria-label="Permalink to &quot;The Trusted `null` Origin Trap&quot;">​</a></h2><p>When developers want to test cross-origin requests locally or allow sandboxed content, they sometimes add <code>null</code> to their CORS allow-list (<code>Access-Control-Allow-Origin: null</code>).</p><p>The <code>Origin: null</code> header is generated in several browser situations:</p><ul><li>HTML documents loaded inside an <code>&lt;iframe sandbox&gt;</code></li><li>Local <code>file://</code> resources</li><li>Cross-origin redirects under certain privacy configurations</li></ul><p>An attacker can host an exploit inside a sandboxed iframe. The browser automatically assigns <code>Origin: null</code> to the outgoing request, satisfying the server&#39;s allow-list and stealing the response!</p>',6)),t(o,{ids:"cors-lab-null-origin-whitelisted-attack"}),e[2]||(e[2]=s('<hr><h2 id="insecure-protocols-amp-subdomain-matching-flaws" tabindex="-1">Insecure Protocols &amp; Subdomain Matching Flaws <a class="header-anchor" href="#insecure-protocols-amp-subdomain-matching-flaws" aria-label="Permalink to &quot;Insecure Protocols &amp;amp; Subdomain Matching Flaws&quot;">​</a></h2><p>Many organizations attempt to validate origins using regular expressions or prefix/suffix checks, but introduce subtle parsing flaws:</p><table tabindex="0"><thead><tr><th>Flaw Pattern</th><th>Implementation Mistake</th><th>How an Attacker Bypasses It</th></tr></thead><tbody><tr><td><strong>Trusting HTTP</strong></td><td>Allowing <code>http://*.example.com</code></td><td>A man-in-the-middle or XSS on an unencrypted subdomain can steal HTTPS data</td></tr><tr><td><strong>Unanchored Regex</strong></td><td>Matching <code>example.com</code> without <code>^</code> or <code>$</code></td><td><code>attacker-example.com</code> or <code>example.com.evil.com</code> matches successfully</td></tr><tr><td><strong>Weak Suffix Check</strong></td><td>Using <code>.endsWith(&quot;example.com&quot;)</code></td><td><code>notexample.com</code> matches the suffix check</td></tr></tbody></table>',4)),t(o,{ids:"cors-lab-breaking-https-attack"}),e[3]||(e[3]=s('<details class="details custom-block"><summary>💡 Detective Distinction: CORS vs. CSRF</summary><p>It is common for beginners to confuse CORS and CSRF:</p><ul><li><strong>CSRF is about WRITING (Actions):</strong> An attacker tricks your browser into performing an action (like changing an email or posting a message). The attacker does not need to read the server&#39;s answer.</li><li><strong>CORS is about READING (Data Theft):</strong> An attacker wants to read private data (like account balances, personal messages, or API keys). The Same-Origin Policy stops the read; flawed CORS headers unlock it.</li></ul></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The Detective&#39;s Defense Blueprint.</strong> Never dynamically reflect incoming <code>Origin</code> headers into <code>Access-Control-Allow-Origin</code>. Maintain a strict, hardcoded allow-list of exact HTTPS origins. Never allow the <code>null</code> origin. Always send the <code>Vary: Origin</code> header whenever responses vary by origin. Remember that CORS is an access control mechanism for browsers, not authentication.</p></div>',2)),t(r,{"topic-id":"cross-origin-resource-sharing-cors",label:"Mark CORS complete"})])}const f=i(c,[["render",l]]);export{v as __pageData,f as default};
